import collections
counts = collections.Counter(); bad = 0
for line in open('access.log'):
    parts = line.split('"')
    try:
        status = int(parts[2].split()[0]); counts[status] += 1
    except Exception:
        bad += 1
print('parsed:', sum(counts.values()), 'unparseable:', bad)
print(dict(sorted(counts.items())))

import csv, collections
rows = list(csv.DictReader(open('temp_log.csv')))
by_day = collections.defaultdict(list)
for r in rows: by_day[r['timestamp'][:10]].append(float(r['temperature_c']))
for d in sorted(by_day):
    print(d, 'n=', len(by_day[d]), 'mean=', round(sum(by_day[d])/len(by_day[d]), 2))

import csv, collections
rows = list(csv.DictReader(open('contacts.csv')))
by_email = collections.Counter(r['email'].strip().lower() for r in rows)
exact = {e: c for e, c in by_email.items() if c > 1}
by_name = collections.defaultdict(set)
for r in rows: by_name[r['name'].strip().lower()].add(r['email'].strip().lower())
probable = {n: e for n, e in by_name.items() if len(e) > 1}
print('exact duplicate email rows:', sum(exact.values()), 'unique emails duplicated:', len(exact))
print('same name, different emails:', len(probable))

import csv, collections
tot = collections.defaultdict(float)
for r in csv.DictReader(open('receipts.csv')):
    tot[r['category']] += float(r['amount'])
for k, v in sorted(tot.items()): print(k, round(v, 2))
